import math

def combinations(n, k):
    return math.comb(n, k)

def calculate_M_star(N):
    # M(N) for a star graph S_N is the number of pairs among the N-1 leaves, 
    # as they are all non-adjacent and share the central node as a common friend.
    if N < 3:
        return 0
    return combinations(N - 1, 2)

N_values = [4, 6, 8]
results = {}
for N in N_values:
    M_N = calculate_M_star(N)
    results[N] = M_N
    print(f"For N={N}, M(N) based on star graph structure: {M_N}")
